it('includes field paths in validation failure messages', async () => {
  const registry = new ToolRegistry();
  registry.register(
    {
      name: 'nested_tool',
      description: 'Nested properties',
      inputSchema: {
        type: 'object',
        properties: {
          outer: {
            type: 'object',
            properties: {inner: {type: 'string'}},
          },
        },
      },
    },
    async () => 'ok'
  );

  const response = await registry.execute('nested_tool', {outer: {inner: 123}});
  expect(response.result).toContain('at /outer/inner');
});

